import { existsSync, readdirSync } from "node:fs";
import path from "node:path";
import type { LoadedRegistry } from "./index";

/** Repo-relative path of the generated demo map (gitignored, built by `pnpm gen:demos`). */
export const DEMO_MAP_PATH = "lib/registry/demos.generated.ts";

export const DEMO_MAP_HEADER =
  "// Generated by scripts/gen-demos.ts from registry/**/<item>/demos/*.tsx. Do not edit; run `pnpm gen:demos`.";

export interface DemoEntry {
  item: string;
  demo: string;
  /** Repo-relative POSIX path of the demo file. */
  path: string;
}

/** Plain code-point order, so the output is identical on every OS and locale. */
function compare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Finds every demo of every item that ships files. An item's folder is the folder of its
 * first file; its demos are the `.tsx` files directly inside `<folder>/demos/`.
 * Throws naming each item that has no `demos/default.tsx`.
 */
export function collectDemos(registry: LoadedRegistry, rootDir = process.cwd()): DemoEntry[] {
  const entries: DemoEntry[] = [];
  const missing: string[] = [];

  for (const item of registry.items) {
    const first = item.files[0];
    if (!first) continue;
    const demosDir = path.posix.join(path.posix.dirname(first.path), "demos");
    const absolute = path.resolve(rootDir, demosDir);
    const files = existsSync(absolute)
      ? readdirSync(absolute).filter((file) => file.endsWith(".tsx"))
      : [];
    if (!files.includes("default.tsx")) {
      missing.push(`${item.name} (expected ${demosDir}/default.tsx)`);
      continue;
    }
    for (const file of files) {
      entries.push({
        item: item.name,
        demo: file.slice(0, -".tsx".length),
        path: `${demosDir}/${file}`,
      });
    }
  }

  if (missing.length > 0) {
    throw new Error(`Registry items without a default demo:\n  ${missing.join("\n  ")}`);
  }

  return entries.sort((a, b) => compare(a.item, b.item) || compare(a.demo, b.demo));
}

/** Renders the demo map module: a data list plus lazy loaders keyed by item, then demo. */
export function renderDemoMap(entries: DemoEntry[]): string {
  const byItem = new Map<string, DemoEntry[]>();
  for (const entry of entries) {
    byItem.set(entry.item, [...(byItem.get(entry.item) ?? []), entry]);
  }

  const list = entries.map(
    (entry) =>
      `  { item: ${JSON.stringify(entry.item)}, demo: ${JSON.stringify(entry.demo)}, path: ${JSON.stringify(entry.path)} },`,
  );
  const loaders = [...byItem].map(([item, demos]) => {
    const lines = demos.map(
      (entry) =>
        `    ${JSON.stringify(entry.demo)}: () => import(${JSON.stringify(`@/${entry.path.slice(0, -".tsx".length)}`)}),`,
    );
    return `  ${JSON.stringify(item)}: {\n${lines.join("\n")}\n  },`;
  });

  return [
    DEMO_MAP_HEADER,
    'import type { ComponentType } from "react";',
    "",
    "export type DemoModule = { default: ComponentType };",
    "export type DemoLoader = () => Promise<DemoModule>;",
    "",
    "export const demoEntries: readonly { item: string; demo: string; path: string }[] = [",
    ...list,
    "];",
    "",
    "export const demoLoaders: Record<string, Record<string, DemoLoader>> = {",
    ...loaders,
    "};",
    "",
  ].join("\n");
}
